using TdLib.TdApi;
using TdLib.TdApi.Objects;
namespace TdLib.Api.OpenTelemetry;
/// <summary>
/// Autogenerated TDLib APIs
/// </summary>

public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Sends a suggested post based on a previously sent message in a channel direct messages chat. Can be also used to suggest price or time change for an existing suggested post.
    /// Returns the sent message
    /// </summary>
    public Task<TdLib.TdApi.Objects.Message> AddOfferAsync(long chatId = default, long messageId = default, MessageSendOptions options = default)
    {

           using var activity =  StartCallActivity("AddOfferAsync", typeof(AddOffer).FullName ?? "AddOfferAsync");

           try
           {
             return client.AddOfferAsync(chatId, messageId, options);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
// REUSE-IgnoreEnd